<?php require_once 'db.php'; require_login(); $page_title='My Bookings'; $s=db()->prepare("SELECT * FROM bookings WHERE user_id=? ORDER BY created_at DESC");$s->execute([$_SESSION['user_id']]);$items=$s->fetchAll();include 'header.php'; ?>
<section class="section"><div class="eyebrow">YOUR DASHBOARD</div><h1 style="font-size:3rem">Your activity, in one place.</h1><div class="panel table-wrap"><table><thead><tr><th>Reference</th><th>Item</th><th>Details</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($items as $b): ?><tr><td>#<?= (int)$b['id'] ?></td><td><?= h($b['item_name']) ?></td><td><?= h($b['details']) ?></td><td>₹<?= number_format($b['amount'],2) ?></td><td><span class="tag"><?= h($b['status']) ?></span></td><td><a href="ticket.php?id=<?= (int)$b['id'] ?>">View / print</a> · <a href="cancel.php?id=<?= (int)$b['id'] ?>">Cancel</a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="6">No bookings yet. Explore the site to get started.</td></tr><?php endif; ?></tbody></table></div></section><?php include 'footer.php'; ?>